NodeEventRegistry::NodeEventRegistry():mappings_{},size_(0U),locked_(false){}RuntimeIntegrationResult NodeEventRegistry::registerMapping(const NodeEventMapping& m){if(locked_)return RuntimeIntegrationResult::REGISTRY_LOCKED;if(!m.isValid())return RuntimeIntegrationResult::INVALID_INPUT;if(find(m.signal())!=nullptr)return RuntimeIntegrationResult::DUPLICATE_MAPPING;if(size_>=NODE_EVENT_MAX_MAPPINGS)return RuntimeIntegrationResult::REGISTRY_FULL;mappings_[size_++]=m;return RuntimeIntegrationResult::SUCCESS;}const NodeEventMapping* NodeEventRegistry::find(NodeEventSignal s)const{for(size_t i=0U;i<size_;++i)if(mappings_[i].signal()==s)return &mappings_[i];return nullptr;}const NodeEventMapping* NodeEventRegistry::at(size_t i)const{return i<size_?&mappings_[i]:nullptr;}size_t NodeEventRegistry::size()const{return size_;}size_t NodeEventRegistry::capacity()const{return NODE_EVENT_MAX_MAPPINGS;}bool NodeEventRegistry::isLocked()const{return locked_;}RuntimeIntegrationResult NodeEventRegistry::lock(){locked_=true;return RuntimeIntegrationResult::SUCCESS;}
